unsafe fn map_transmitter_id_to_phy_instance(transmitter: transmitter) -> i32 {
    match transmitter { TRANSMITTER_UNIPHY_A => 0, TRANSMITTER_UNIPHY_B => 1, TRANSMITTER_UNIPHY_C => 2, TRANSMITTER_UNIPHY_D => 3, TRANSMITTER_UNIPHY_E => 4, TRANSMITTER_UNIPHY_F => 5, TRANSMITTER_UNIPHY_G => 6, _ => { ASSERT(0); 0 } }
}

unsafe fn read_dce_straps(ctx: *mut dc_context, straps: *mut resource_straps) {
    REG_GET_2!(ctx, CC_DC_HDMI_STRAPS, HDMI_DISABLE, &mut (*straps).hdmi_disable);
    REG_GET_2!(ctx, CC_DC_HDMI_STRAPS, AUDIO_STREAM_NUMBER, &mut (*straps).audio_stream_number);
    REG_GET!(ctx, DC_PINSTRAPS, DC_PINSTRAPS_AUDIO, &mut (*straps).dc_pinstraps_audio);
}

unsafe fn create_audio(ctx: *mut dc_context, inst: u32) -> *mut audio { dce_audio_create(ctx, inst, &audio_regs[inst as usize], &audio_shift, &audio_mask) }

unsafe fn dce112_timing_generator_create(ctx: *mut dc_context, instance: u32, offsets: *const dce110_timing_generator_offsets) -> *mut timing_generator {
    let tg110 = kzalloc_obj::<dce110_timing_generator>(); if tg110.is_null() { return core::ptr::null_mut(); }
    dce110_timing_generator_construct(tg110, ctx, instance, offsets); &mut (*tg110).base
}

unsafe fn dce112_stream_encoder_create(eng_id: engine_id, ctx: *mut dc_context) -> *mut stream_encoder {
    let enc110 = kzalloc_obj::<dce110_stream_encoder>(); if enc110.is_null() { return core::ptr::null_mut(); }
    dce110_stream_encoder_construct(enc110, ctx, (*ctx).dc_bios, eng_id, &stream_enc_regs[eng_id as usize], &se_shift, &se_mask); &mut (*enc110).base
}

unsafe fn dce112_hwseq_create(ctx: *mut dc_context) -> *mut dce_hwseq {
    let hws = kzalloc_obj::<dce_hwseq>(); if !hws.is_null() { (*hws).ctx = ctx; (*hws).regs = &hwseq_reg; (*hws).shifts = &hwseq_shift; (*hws).masks = &hwseq_mask; } hws
}

