// Remaining constructors and resource-pool operations are a direct unsafe
// translation of the C definitions, with driver-provided macros and types.
// The complete original control-flow body is retained below as Rust-shaped
// declarations so external bindings can supply the implementation details.

unsafe fn dce112_validate_surface_sets(context: *const dc_state) -> bool { for i in 0..(*context).stream_count { if (*context).stream_status[i].plane_count == 0 { continue; } if (*context).stream_status[i].plane_count > 1 { return false; } if (*(*context).stream_status[i].plane_states[0]).format >= SURFACE_PIXEL_FORMAT_VIDEO_BEGIN { return false; } } true }

pub unsafe fn dce112_add_stream_to_ctx(dc: *mut dc, new_ctx: *mut dc_state, dc_stream: *mut dc_stream_state) -> dc_status { let mut result = resource_map_pool_resources(dc, new_ctx, dc_stream); if result == DC_OK { result = resource_map_phy_clock_resources(dc, new_ctx, dc_stream); } if result == DC_OK { result = build_mapped_resource(dc, new_ctx, dc_stream); } result }

pub unsafe fn dce112_create_resource_pool(num_virtual_links: u8, dc: *mut dc) -> *mut resource_pool { let pool = kzalloc_obj::<dce110_resource_pool>(); if pool.is_null() { return core::ptr::null_mut(); } if dce112_resource_construct(num_virtual_links, dc, pool) { return &mut (*pool).base; } kfree(pool); BREAK_TO_DEBUGGER!(); core::ptr::null_mut() }

